import pkg_resources

from typing import Union
from bs4 import BeautifulSoup as Soup
from dataclasses import dataclass
from pathlib import Path

from taf.rfrl.utilities.robot.general import get_builtin_value

from taf.rfrl.csv4all.resources.test_reporter.csv4all_test_reporter import CSV4AllTestReporter


@dataclass
class EmailFormat:
    nodes: list = None
    test_nodes: list = None
    report_to_rp: bool = False
    test_reporter: CSV4AllTestReporter = None
    iterations_per_node: int = 0
    state: str = ""
    msg: str = ""
    topology: str = ""
    execution_link: str = ""
    test_results: dict = None
    current_iteration: str = "1"
    netact_name: str = None

    def __repr__(self):
        return self._convert_email_to_html(self._get_email_body_dict())

    def _convert_email_to_html(self, body_dict: dict) -> str:

        def fill_html() -> str:
            p = Path(__file__).with_name("email_template.html")
            with p.open("r") as template_file:
                html_content = template_file.read()
                soup = Soup(html_content, "html.parser")
                body = soup.find("body")
                head = soup.find("head")
                results = f"<hr><b>Test Results</b>: {final_results}" if final_results else ""
                rfrl_info = f'Test was executed using: <b id="rfrlVersion">{rfrl_version}</b>'
                head.append(Soup(rfrl_info + results, "html.parser"))
                body.append(Soup(body_to_html + fdsw_builds + firmware_info + last_issues + test_reports,
                                 "html.parser"))
                return soup.prettify()

        rfrl_version = body_dict.pop("CSV4ALL Version", None)
        test_results = body_dict.pop("Test Results", {})
        test_reports = self._format_test_reports(body_dict.pop("Test Reports", None))
        last_issues = self._format_issues_content() if self.state == "failed" else ""
        fdsw_builds = self._format_dnr_table(body_dict.pop("FDSW Builds", None))
        firmware_info = self._format_firmware_info(body_dict.pop("Firmware upgrade", None))
        body_dict = {key: value for key, value in body_dict.items() if key}
        body_to_html = "<div>" + "".join([f"<b>{key}</b>: {value}<br>" for key, value in body_dict.items()]) + "</div>"
        final_results = f"""
        <b id="passedText">Passed: {sum(nodes_result == "passed" for nodes_result in test_results.values())} 
        &emsp;</b>
        <b id="failedText">Failed: {sum(nodes_result == "failed" for nodes_result in test_results.values())} 
        &emsp;</b>""" if test_results else None
        return fill_html()

    def _get_email_body_dict(self) -> dict:
        test_nodes = ', '.join([node.node_alias for node in self.test_nodes])
        fdsw_builds = {node.node_alias: node.fdsw_builds for node in self.test_nodes if node.fdsw_builds}
        firmware_upgrade = {node.node_alias: node.uboot.fw_status_to_rp for node in self.test_nodes
                            if node.uboot.fw_status_to_rp}
        customers = self.test_reporter.customers_list if self.test_reporter else None
        rfrl_version = str(pkg_resources.get_distribution('taf-rfrl-csv4all')).replace("-", ".")
        candidate = ', '.join({str(node.target_sw) for node in self.test_nodes})
        initial = ', '.join({str(node.source_sw) for node in self.test_nodes})
        nodes = ', '.join([node.node_alias for node in self.nodes])
        execution_link = f"""<a href={self.execution_link}>Logs</a>""" if self.execution_link else None
        body_dict = {"CSV4ALL Version": rfrl_version,
                     "Username": self.test_reporter.tester_name if self.test_reporter else None,
                     "Test Case": get_builtin_value('TEST NAME').title(),
                     "Topology": self.topology,
                     "Candidate": candidate,
                     "Initial": initial,
                     "Test Nodes": test_nodes,
                     "Nodes": nodes,
                     "Loops": self.iterations_per_node,
                     "UTE execution": bool(execution_link),
                     "Execution logs link": execution_link,
                     "Report": self.report_to_rp,
                     "FDSW Builds": fdsw_builds or None,
                     "Firmware upgrade": firmware_upgrade or None}
        if self.netact_name:
            pos = list(body_dict.keys()).index('Test Case')
            items = list(body_dict.items())
            items.insert(pos, ('Netact', self.netact_name))
            body_dict = dict(items)
        if self.test_reporter:
            if self.state == "ended":
                body_dict.update({"Fetch Scout SCF": 'PASS' if self.test_reporter.test_id else 'FAIL'})
            body_dict.update({"Test Reports": self.test_reporter.report_dict})
        if self.report_to_rp:
            body_dict.update({"Customers": ", ".join(customers)})
        if self.state in ("failed", "ended"):
            body_dict.update({"Test Results": self.test_results})
        if self.state == "failed":
            body_dict.update({"Current Iteration": self.current_iteration})
        if self.msg:
            body_dict.update({"Additional message": self.msg})
        return body_dict

    @staticmethod
    def _format_dnr_table(fdsw_builds: Union[dict, None]) -> str:
        if not fdsw_builds:
            return ""
        fdsw_builds_content = f"""<hr><h3>DnR Informations</h3>"""
        for mrbts in fdsw_builds.keys():
            fdsw_builds_content += f"""<table>
                <caption><b>{mrbts}</b></caption>
                <tr>
                    <th>SMOD</th>
                    <th>Phase</th>
                    <th>FS3 Partition</th>
                    <th>Active Partition</th>
                    <th>Passive Partition</th>
                </tr>"""
            for smod in fdsw_builds[mrbts]:
                for phase, details in fdsw_builds[mrbts][smod].items():
                    fdsw_builds_content += f"""
                    <tr>
                        <td><b>{smod}</b></td>
                        <td><b>{phase}</b></td>
                        <td>{details['fs3']}</td>
                        <td>{details['active']}</td>
                        <td>{details['passive']}</td>
                    </tr>
                    """
            fdsw_builds_content += f"""</table><br>"""
        return fdsw_builds_content

    @staticmethod
    def _format_firmware_info(firmware: Union[dict, None]) -> str:
        if not firmware:
            return ""
        firmware_content = f"""<br><hr><h3>Firmware Downgrade Informations</h3>"""
        for mrbts, firmware_info in firmware.items():
            firmware_content += f"""<b>{mrbts}</b>: {firmware_info}<br>"""
        return firmware_content

    @staticmethod
    def _format_test_reports(test_reports: Union[dict, None]) -> str:
        if not test_reports:
            return ""
        reports_content = f"""<br><hr><h3>Test Reports</h3>"""
        for mrbts, iterations in test_reports.items():
            reports_content += f"""<b>Iterations for {mrbts}</b><ol>"""
            for iteration, details in iterations.items():
                status_id = "passedText" if details["Result"] == "passed" else "failedText"
                reports_content += f"""<li><b id="{status_id}">{details["Result"].capitalize()}</b>
                <a href="{details["Link to report"]}">Link to RP</a></li>"""
            reports_content += """</ol>"""
        return reports_content

    def _format_issues_content(self) -> str:
        def get_fault_messages(fault_message_list):
            fault_messages = ""
            for message in fault_message_list:
                fault_messages += f"""<p>{message}</p>"""
            return fault_messages

        issues_content = ""
        for node in self.test_nodes:
            if node.btsverify.bts_fault_message == "" and node.logsverify.logs_fault_message == "":
                continue
            logs_fault_messages = get_fault_messages(node.logsverify.logs_fault_message.split('\n'))
            bts_fault_messages = get_fault_messages(node.btsverify.bts_fault_message.split("\n"))
            issues_content += f"""
            <h3>{node.node_alias} Issues</h3>{logs_fault_messages}{bts_fault_messages}"""
        if issues_content:
            issues_content = f"<br><hr>{issues_content}"
        return issues_content
